using System;using System.IO;using System.Linq;using SignalWorkbench;
class FilterChecks {
 static void Main(string[] args){try{Run(args);}catch(Exception ex){Console.WriteLine(ex.Message);Environment.ExitCode=1;}}
 static void Run(string[] args){string dir=args[0];Directory.CreateDirectory(dir);int id=0;
 foreach(string response in new[]{"Lowpass","Highpass","Bandpass","Bandstop"}){
 foreach(string window in Engine.Windows)foreach(int order in new[]{2,31,64,255}){if(order%2==1&&(response=="Highpass"||response=="Bandstop"))continue;var s=new FilterSettings{Response=response,Window=window,Order=order,WindowParameter=window=="Tukey"?.5:window=="Gaussian"?16:8.6,Width=32,Fraction=26};Write(dir,id++,s);}
 foreach(string method in new[]{"Butterworth","ChebyshevI","ChebyshevII"})foreach(int order in new[]{1,2,3,4,7,12})foreach(double f in new[]{500.0,5000,15000}){var s=new FilterSettings{Structure="IIR",Method=method,Response=response,Order=order,F1=f,F2=f+3000,Width=32,Fraction=26,Format="ROM COE"};Write(dir,id++,s);}}
 var def=Filters.Design(new FilterSettings());Filters.ExportCoe(Path.Combine(dir,"fir.coe"),def,"FIR COE");Filters.ExportCoe(Path.Combine(dir,"fir_rom.coe"),def,"ROM COE");Filters.ExportCoe(Path.Combine(dir,"fir.mif"),def,"Altera MIF");Filters.ExportSignal(Path.Combine(dir,"filtered.csv"),def);
 bool rejected=false;try{Filters.FirDesign(new FilterSettings{Response="Highpass",Order=31});}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("odd order guard");
 var low=Filters.Design(new FilterSettings{Structure="IIR",Order=4,F1=1000,Width=4,Fraction=1});if(low.StableQ)throw new Exception("unstable quantization not detected");rejected=false;try{Filters.ExportCoe(Path.Combine(dir,"unsafe.coe"),low,"ROM COE");}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("unstable export guard");
 foreach(string method in new[]{"Butterworth","ChebyshevI","ChebyshevII"})foreach(string type in new[]{"Lowpass","Highpass","Bandpass","Bandstop"}){var r=Filters.Design(new FilterSettings{Structure="IIR",Method=method,Response=type,Order=4,Format="ROM COE"});if(!r.StableQ)throw new Exception("default IIR unstable");Filters.ExportCoe(Path.Combine(dir,"iir_"+method+"_"+type+".coe"),r,"ROM COE");}
 string input=Path.Combine(dir,"input.csv");File.WriteAllText(input,"index,value\n"+string.Join("\n",Enumerable.Range(0,16).Select(i=>i+","+(i*.25).ToString(Engine.CI))));var data=Filters.ReadSignal(input,2);if(data.Length!=16||data[15]!=3.75)throw new Exception("CSV column import");foreach(string bad in new[]{"NaN","nan","Infinity","1e309"}){File.WriteAllText(input,bad+"\n"+string.Join("\n",Enumerable.Repeat("1",16)));rejected=false;try{Filters.ReadSignal(input,1);}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("invalid CSV numeric header accepted");}
 var imported=Filters.Design(new FilterSettings{TestSignal="Imported"},data);if(!imported.Input.SequenceEqual(data))throw new Exception("imported filtering");
 var settings=new FilterSettings{Structure="IIR",Order=4,Method="ChebyshevII",Format="Altera MIF"};settings.Save(Path.Combine(dir,"settings_roundtrip.xml"));var loaded=FilterSettings.Load(Path.Combine(dir,"settings_roundtrip.xml"));if(loaded.Method!=settings.Method||loaded.Format!=settings.Format)throw new Exception("settings roundtrip");
 Console.WriteLine("PASS "+id+" reference designs; 12 default IIR designs; exports, parity/stability guards, CSV import and invalid input guards, XML roundtrip");}
 static void Write(string dir,int id,FilterSettings s){var r=Filters.Design(s);string prefix=Path.Combine(dir,id.ToString());s.Save(prefix+".xml");Filters.ExportCoefficients(prefix+".csv",r);using(var w=new StreamWriter(prefix+".response.csv")){for(int i=0;i<257;i++){var h=Filters.Response(r.Fir,r.Sos,Math.PI*i/256);w.WriteLine(Engine.F(h.Real)+","+Engine.F(h.Imaginary));}}using(var w=new StreamWriter(prefix+".impulse.csv"))foreach(double v in r.Impulse)w.WriteLine(Engine.F(v));}
}
